//! Hand-written parser for the patterned PowerVR register headers.
//!
//! These headers are autogenerated C: every control register is a base offset
//! plus, per field, `*_SHIFT` / `*_CLRMSK` / optional `*_EN` and named values.
//! A dedicated parser is smaller and more predictable than bindgen, and keeps
//! the generator off the kernel build's critical path.

use std::collections::BTreeMap;

/// Width of a C integer literal, inferred from its suffix.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IntWidth {
    /// `U` / bare — invert clear-masks in 32 bits (upstream 32-bit regs).
    U32,
    /// `ULL` / `LL` — invert clear-masks in 64 bits.
    U64,
}

/// One bitfield inside a control register.
#[derive(Clone, Debug)]
pub struct FieldDef {
    pub name: String,
    pub shift: u32,
    pub clrmsk: u64,
    /// Width of the upstream `*_CLRMSK` literal; controls how `mask` is derived.
    pub clrmsk_width: IntWidth,
    /// Positioned enable value, if the header provides `*_EN`.
    pub en: Option<u64>,
    /// Other named values for this field (OFF/ON/AUTO, DM0, …), in header order.
    pub values: Vec<(String, u64)>,
}

impl FieldDef {
    pub fn mask(&self) -> u64 {
        match self.clrmsk_width {
            IntWidth::U32 => (!(self.clrmsk as u32)) as u64,
            IntWidth::U64 => !self.clrmsk,
        }
    }
}

/// One control register: offset plus fields.
#[derive(Clone, Debug)]
pub struct Register {
    pub name: String,
    pub offset: u32,
    pub fields: Vec<FieldDef>,
    /// `*_MASKFULL` defines under this register, in header order, as
    /// `(rust identifier, upstream define name, value)`.
    ///
    /// The whole-register write masks. `pvr_fw_startstop.c` writes these
    /// directly — `ROGUE_CR_SOFT_RESET_MASKFULL` is what "put Rogue in
    /// soft-reset" means — so they cannot be treated as documentation the way
    /// the earlier generator did. Config variants (`__PBE2_XE__MASKFULL`,
    /// `__XE_MEM__MASKFULL`) are separate entries because the driver picks
    /// between them on a feature bit.
    pub maskfulls: Vec<(String, String, u64)>,
    /// Bare constants under this register that are not field-shaped
    /// (leftover named values land here).
    pub constants: Vec<(String, u64)>,
}

/// Parse errors are fatal: totality forbids silent skips of allow-listed items.
#[derive(Debug)]
pub struct ParseError(pub String);

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl std::error::Error for ParseError {}

/// Strip C comments and join continued lines so `#define`s are one line each.
pub fn preprocess(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let bytes = input.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if i + 1 < bytes.len() && bytes[i] == b'/' && bytes[i + 1] == b'*' {
            i += 2;
            while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
                i += 1;
            }
            i = i.saturating_add(2);
            continue;
        }
        if i + 1 < bytes.len() && bytes[i] == b'/' && bytes[i + 1] == b'/' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
            }
            continue;
        }
        out.push(bytes[i] as char);
        i += 1;
    }

    let mut joined = String::with_capacity(out.len());
    for line in out.lines() {
        let trimmed = line.trim_end();
        if trimmed.ends_with('\\') {
            joined.push_str(trimmed.trim_end_matches('\\').trim_end());
            joined.push(' ');
        } else {
            joined.push_str(trimmed);
            joined.push('\n');
        }
    }
    joined
}

/// Parse a C integer token: `0x…`, decimal, optional `U`/`ULL`/`ull` suffix,
/// optional surrounding parentheses.
pub fn parse_int(token: &str) -> Result<u64, ParseError> {
    Ok(parse_int_width(token)?.0)
}

/// Like [`parse_int`], but also reports the literal width from its suffix.
pub fn parse_int_width(token: &str) -> Result<(u64, IntWidth), ParseError> {
    let mut s = token.trim();
    while s.starts_with('(') && s.ends_with(')') {
        s = s[1..s.len() - 1].trim();
    }
    let width =
        if s.ends_with("ULL") || s.ends_with("ull") || s.ends_with("LL") || s.ends_with("ll") {
            IntWidth::U64
        } else {
            // `U`/`u` or unsuffixed: treat as 32-bit for CLRMSK inversion. Upstream
            // uses bare decimals for shifts and `U` for 32-bit masks.
            IntWidth::U32
        };
    let s = s
        .trim_end_matches("ULL")
        .trim_end_matches("ull")
        .trim_end_matches("LL")
        .trim_end_matches("ll")
        .trim_end_matches('U')
        .trim_end_matches('u');
    let value = if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(hex, 16).map_err(|e| ParseError(format!("bad hex `{token}`: {e}")))?
    } else {
        s.parse::<u64>()
            .map_err(|e| ParseError(format!("bad int `{token}`: {e}")))?
    };
    Ok((value, width))
}

/// Collect simple `#define NAME <int>` from preprocessed text (skips function macros).
pub fn parse_simple_defines(text: &str) -> Result<BTreeMap<String, u64>, ParseError> {
    let text = preprocess(text);
    let mut map = BTreeMap::new();
    for (lineno, line) in text.lines().enumerate() {
        let line = line.trim();
        if !line.starts_with("#define") {
            continue;
        }
        let rest = line["#define".len()..].trim_start();
        let mut parts = rest.split_whitespace();
        let Some(name) = parts.next() else {
            continue;
        };
        if name.contains('(') {
            // Function-like macro: not a constant. Totality applies only to
            // allow-listed registers / constants we claim to emit.
            continue;
        }
        let Some(value_tok) = parts.next() else {
            continue;
        };
        // Only accept a lone integer token (optionally parenthesized).
        if parts.next().is_some() {
            continue;
        }
        if !(value_tok.starts_with("0x")
            || value_tok.starts_with("0X")
            || value_tok.starts_with('(')
            || value_tok.chars().next().is_some_and(|c| c.is_ascii_digit()))
        {
            continue;
        }
        match parse_int(value_tok) {
            Ok(v) => {
                map.insert(name.to_string(), v);
            }
            Err(e) => {
                return Err(ParseError(format!(
                    "line {}: define {name}: {e}",
                    lineno + 1
                )));
            }
        }
    }
    Ok(map)
}

/// Parse CR headers from raw source (keeps `/* Register … */` markers).
pub fn parse_cr_from_source(sources: &[&str]) -> Result<BTreeMap<String, Register>, ParseError> {
    let mut regs = BTreeMap::new();
    for src in sources {
        parse_one_cr_source(src, &mut regs)?;
    }
    Ok(regs)
}

fn parse_one_cr_source(src: &str, regs: &mut BTreeMap<String, Register>) -> Result<(), ParseError> {
    // Join line continuations but keep block comments that are register markers.
    let joined = join_continuations(src);
    let marker = "/* Register ";
    let mut positions: Vec<(usize, String)> = Vec::new();
    let mut search = 0;
    while let Some(rel) = joined[search..].find(marker) {
        let start = search + rel;
        let name_start = start + marker.len();
        let Some(end_rel) = joined[name_start..].find(" */") else {
            return Err(ParseError("unterminated /* Register … */ marker".into()));
        };
        let comment_name = joined[name_start..name_start + end_rel].trim().to_string();
        positions.push((start, comment_name));
        search = name_start + end_rel + 3;
    }

    for (idx, (start, _comment_name)) in positions.iter().enumerate() {
        let end = positions
            .get(idx + 1)
            .map(|(s, _)| *s)
            .unwrap_or(joined.len());
        let block = &joined[*start..end];
        let block = strip_block_and_line_comments(block);
        let defines = parse_define_lines(&block)?;
        if defines.is_empty() {
            return Err(ParseError(format!(
                "register block at byte {start} has no #define"
            )));
        }
        // First define whose RHS is a bare integer is the register offset.
        // Name may differ from the comment when the define is a variant
        // (`ROGUE_CR_CORE_ID__PBVNC` under comment `ROGUE_CR_CORE_ID`).
        let (reg_name, offset, _) = &defines[0];
        if *offset > u32::MAX as u64 {
            return Err(ParseError(format!(
                "register {reg_name} offset does not fit u32"
            )));
        }
        let reg_name = reg_name.clone();
        let offset = *offset as u32;

        let field_sep = if reg_name.contains("__") { "__" } else { "_" };
        let prefix = format!("{reg_name}{field_sep}");

        let mut by_name: BTreeMap<String, (u64, IntWidth)> = BTreeMap::new();
        for (n, v, w) in &defines[1..] {
            by_name.insert(n.clone(), (*v, *w));
        }

        // Discover fields from *_SHIFT keys.
        let mut field_names: Vec<String> = Vec::new();
        for n in by_name.keys() {
            if let Some(rest) = n.strip_prefix(&prefix) {
                if let Some(field) = rest.strip_suffix("_SHIFT") {
                    if !field.is_empty() {
                        field_names.push(field.to_string());
                    }
                }
            }
        }
        // Preserve header order.
        field_names.sort_by_key(|f| {
            defines
                .iter()
                .position(|(n, _, _)| n == &format!("{prefix}{f}_SHIFT"))
                .unwrap_or(usize::MAX)
        });
        field_names.dedup();

        let mut fields = Vec::new();
        let mut consumed = std::collections::HashSet::new();
        // MASKFULL variants / plain. Collected in header order so the emitted
        // order does not depend on how the names happen to sort.
        let mut maskfulls: Vec<(String, String, u64)> = Vec::new();
        for (n, v, _) in &defines[1..] {
            if !(n.contains("MASKFULL") && n.starts_with(&reg_name)) {
                continue;
            }
            if !consumed.insert(n.clone()) {
                continue;
            }
            let ident = n[reg_name.len()..].trim_start_matches('_');
            if ident.is_empty() {
                return Err(ParseError(format!(
                    "{reg_name}: MASKFULL define `{n}` has no suffix"
                )));
            }
            maskfulls.push((ident.to_string(), n.clone(), *v));
        }
        for fname in &field_names {
            let shift_k = format!("{prefix}{fname}_SHIFT");
            let clrmsk_k = format!("{prefix}{fname}_CLRMSK");
            let Some(&(shift, _)) = by_name.get(&shift_k) else {
                return Err(ParseError(format!(
                    "{reg_name}: field {fname} missing SHIFT"
                )));
            };
            let Some(&(clrmsk, clrmsk_width)) = by_name.get(&clrmsk_k) else {
                return Err(ParseError(format!(
                    "{reg_name}: field {fname} has SHIFT but no CLRMSK (totality)"
                )));
            };
            consumed.insert(shift_k);
            consumed.insert(clrmsk_k);

            let en_k = format!("{prefix}{fname}_EN");
            let en = by_name.get(&en_k).map(|(v, _)| *v);
            if en.is_some() {
                consumed.insert(en_k);
            }

            // ALIGNSHIFT / ALIGNSIZE accompany some fields.
            for suffix in ["_ALIGNSHIFT", "_ALIGNSIZE"] {
                let k = format!("{prefix}{fname}{suffix}");
                if by_name.contains_key(&k) {
                    consumed.insert(k);
                }
            }

            let value_prefix = format!("{prefix}{fname}_");
            let mut values = Vec::new();
            for (n, v, _) in &defines[1..] {
                if consumed.contains(n) {
                    continue;
                }
                if let Some(rest) = n.strip_prefix(&value_prefix) {
                    // Avoid treating another field's keys as values:
                    // e.g. FIELD_FOO_SHIFT when fname is FIELD.
                    if rest.contains("_SHIFT")
                        || rest.contains("_CLRMSK")
                        || rest.ends_with("_EN")
                        || rest.contains("_ALIGNSHIFT")
                        || rest.contains("_ALIGNSIZE")
                    {
                        continue;
                    }
                    // If rest itself looks like start of a longer field name that
                    // has its own SHIFT, skip — handled by that field.
                    let maybe_longer = format!("{fname}_{rest}");
                    if by_name.contains_key(&format!("{prefix}{maybe_longer}_SHIFT")) {
                        continue;
                    }
                    values.push((rest.to_string(), *v));
                    consumed.insert(n.clone());
                }
            }

            fields.push(FieldDef {
                name: fname.clone(),
                shift: shift as u32,
                clrmsk,
                clrmsk_width,
                en,
                values,
            });
        }

        let mut constants = Vec::new();
        for (n, v, _) in &defines[1..] {
            if consumed.contains(n) {
                continue;
            }
            if let Some(rest) = n.strip_prefix(&prefix) {
                constants.push((rest.to_string(), *v));
            } else if let Some(rest) = n.strip_prefix(&format!("{reg_name}_")) {
                // Variant MASKFULL etc. already consumed; leftovers with single _
                constants.push((rest.to_string(), *v));
            } else if n.starts_with(&reg_name) {
                return Err(ParseError(format!(
                    "{reg_name}: unparsed define `{n}` (totality)"
                )));
            }
        }

        if regs.contains_key(&reg_name) {
            return Err(ParseError(format!(
                "duplicate register definition `{reg_name}`"
            )));
        }
        regs.insert(
            reg_name.clone(),
            Register {
                name: reg_name,
                offset,
                fields,
                maskfulls,
                constants,
            },
        );
    }
    Ok(())
}

fn join_continuations(src: &str) -> String {
    let mut joined = String::with_capacity(src.len());
    for line in src.lines() {
        let trimmed = line.trim_end();
        if trimmed.ends_with('\\') {
            joined.push_str(trimmed.trim_end_matches('\\').trim_end());
            joined.push(' ');
        } else {
            joined.push_str(line);
            joined.push('\n');
        }
    }
    joined
}

fn strip_block_and_line_comments(block: &str) -> String {
    let mut out = String::with_capacity(block.len());
    let bytes = block.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if i + 1 < bytes.len() && bytes[i] == b'/' && bytes[i + 1] == b'*' {
            i += 2;
            while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') {
                i += 1;
            }
            i = i.saturating_add(2);
            out.push(' ');
            continue;
        }
        if i + 1 < bytes.len() && bytes[i] == b'/' && bytes[i + 1] == b'/' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
            }
            continue;
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out
}

fn parse_define_lines(block: &str) -> Result<Vec<(String, u64, IntWidth)>, ParseError> {
    let mut out = Vec::new();
    for line in block.lines() {
        let line = line.trim();
        if !line.starts_with("#define") {
            continue;
        }
        let rest = line["#define".len()..].trim_start();
        let mut parts = rest.split_whitespace();
        let Some(name) = parts.next() else {
            continue;
        };
        if name.contains('(') {
            continue;
        }
        let Some(value_tok) = parts.next() else {
            continue;
        };
        // Allow only pure integer RHS for CR field tables.
        if parts.next().is_some() {
            continue;
        }
        let (value, width) = parse_int_width(value_tok)?;
        out.push((name.to_string(), value, width));
    }
    Ok(out)
}

/// Linux `sizes.h` constants referenced by `pvr_rogue_heap_config.h`.
pub fn linux_size_constants() -> BTreeMap<&'static str, u64> {
    BTreeMap::from([
        ("SZ_2M", 2 * 1024 * 1024),
        ("SZ_256M", 256 * 1024 * 1024),
        ("SZ_4G", 4 * 1024 * 1024 * 1024),
        ("SZ_16G", 16 * 1024 * 1024 * 1024),
        ("SZ_128G", 128 * 1024 * 1024 * 1024),
    ])
}

/// Evaluate a subset of constant expressions used in the small headers.
pub fn eval_expr(expr: &str, env: &BTreeMap<String, u64>) -> Result<u64, ParseError> {
    let expr = expr.trim();
    let mut s = expr.to_string();
    while s.starts_with('(') && s.ends_with(')') && balanced_paren(&s) {
        s = s[1..s.len() - 1].trim().to_string();
    }
    // BIT(n)
    if let Some(inner) = s.strip_prefix("BIT(").and_then(|x| x.strip_suffix(')')) {
        let n = eval_expr(inner, env)?;
        if n >= 64 {
            return Err(ParseError(format!("BIT({n}) out of range")));
        }
        return Ok(1u64 << n);
    }
    // identifier
    if s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        && s.chars()
            .next()
            .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
    {
        if let Some(v) = env.get(&s) {
            return Ok(*v);
        }
        if let Some(v) = linux_size_constants().get(s.as_str()) {
            return Ok(*v);
        }
        return Err(ParseError(format!("unknown identifier `{s}` in expr")));
    }
    // pure int
    if let Ok(v) = parse_int(&s) {
        return Ok(v);
    }
    // binary ops left-to-right for | & << >> + - *
    for op in ["|", "&", "<<", ">>", "+", "-", "*"] {
        if let Some(idx) = find_top_level_op(&s, op) {
            let (l, r) = s.split_at(idx);
            let r = &r[op.len()..];
            let lv = eval_expr(l, env)?;
            let rv = eval_expr(r, env)?;
            return Ok(match op {
                "|" => lv | rv,
                "&" => lv & rv,
                "<<" => lv << rv,
                ">>" => lv >> rv,
                "+" => lv.wrapping_add(rv),
                "-" => lv.wrapping_sub(rv),
                "*" => lv.wrapping_mul(rv),
                _ => unreachable!(),
            });
        }
    }
    Err(ParseError(format!("cannot evaluate expression `{expr}`")))
}

fn balanced_paren(s: &str) -> bool {
    let mut depth = 0;
    for (i, c) in s.chars().enumerate() {
        match c {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 && i != s.len() - 1 {
                    return false;
                }
                if depth < 0 {
                    return false;
                }
            }
            _ => {}
        }
    }
    depth == 0 && s.starts_with('(')
}

fn find_top_level_op(s: &str, op: &str) -> Option<usize> {
    let mut depth = 0;
    let b = s.as_bytes();
    let mut i = 0;
    // rightmost for left-assoc? use leftmost for << consistency with C LTR of same prec — simplify: leftmost
    let mut found = None;
    while i + op.len() <= b.len() {
        let c = b[i] as char;
        if c == '(' {
            depth += 1;
            i += 1;
            continue;
        }
        if c == ')' {
            depth -= 1;
            i += 1;
            continue;
        }
        if depth == 0 && s[i..].starts_with(op) {
            // don't match | inside ||
            if op == "|" && s[i..].starts_with("||") {
                i += 2;
                continue;
            }
            if op == "&" && s[i..].starts_with("&&") {
                i += 2;
                continue;
            }
            found = Some(i);
            i += op.len();
            continue;
        }
        i += 1;
    }
    found
}

/// Parse `#define`s from a small header, evaluating RHS with `env` growing as we go.
///
/// `seed` injects already-known constants (e.g. CR `*_EN` values) so compound
/// macros in `pvr_rogue_defs.h` can resolve.
pub fn parse_evaluable_defines(
    src: &str,
    seed: &BTreeMap<String, u64>,
) -> Result<BTreeMap<String, u64>, ParseError> {
    let joined = join_continuations(src);
    let text = strip_block_and_line_comments(&joined);
    let mut env: BTreeMap<String, u64> = BTreeMap::new();
    for (name, val) in linux_size_constants() {
        env.insert(name.to_string(), val);
    }
    for (k, v) in seed {
        env.insert(k.clone(), *v);
    }
    let mut defined_here = std::collections::BTreeSet::new();
    for line in text.lines() {
        let line = line.trim();
        if !line.starts_with("#define") {
            continue;
        }
        let rest = line["#define".len()..].trim_start();
        if rest.contains('(') && rest.find('(').unwrap() < rest.find(' ').unwrap_or(0) {
            // function-like: skip
            continue;
        }
        let mut parts = rest.splitn(2, char::is_whitespace);
        let Some(name) = parts.next() else {
            continue;
        };
        if name.contains('(') {
            continue;
        }
        let Some(rhs) = parts.next() else {
            continue;
        };
        let rhs = rhs.trim();
        // Skip string literals and includes-of-macros we cannot see.
        if rhs.starts_with('"') {
            continue;
        }
        match eval_expr(rhs, &env) {
            Ok(v) => {
                env.insert(name.to_string(), v);
                defined_here.insert(name.to_string());
            }
            Err(_) => {
                // Leave unevaluated — caller decides if that matters.
            }
        }
    }
    env.retain(|k, _| defined_here.contains(k));
    Ok(env)
}
